import React, { useState, useEffect, useCallback } from 'react';
import { Card, Button, Alert, api } from '../App';


const SectionTitle = ({ n, children }) => (
  <div style={{ fontSize: 11, fontWeight: 700, color: '#444', textTransform: 'uppercase', letterSpacing: 0.6, marginBottom: 10, padding: '6px 0', borderBottom: '1.5px solid #e2e8f0' }}>
    {n ? `${n}. ` : ''}{children}
  </div>
);

const NumCell = ({ value, onChange, placeholder = '0', width = 72 }) => (
  <input type="number" min="0" value={value || ''} onChange={e => onChange(e.target.value)} placeholder={placeholder}
    style={{ width, padding: '5px 8px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 12, textAlign: 'center' }} />
);

export default function MappingPage() {
  const [parties,      setParties]      = useState([]);
  const [allGardens,   setAllGardens]   = useState([]);
  const [allGrades,    setAllGrades]    = useState([]);
  const [allBrokers,   setAllBrokers]   = useState([]);
  const [gradeGardens, setGradeGardens] = useState({}); // NEW: grade -> gardens mapping

  const [selected,     setSelected]     = useState(null);
  const [search,       setSearch]       = useState('');
  const [saving,       setSaving]       = useState(false);
  const [alert,        setAlert]        = useState(null);
  const [addMode,      setAddMode]      = useState(false);
  const [newParty,     setNewParty]     = useState({ name: '', code: '' });
  const [importing,    setImporting]    = useState(false);
  const [importResult, setImportResult] = useState(null);

  // Party master fields
  const [selectedGrades, setSelectedGrades] = useState([]);
  const [mappedGardens,  setMappedGardens]  = useState([]);
  const [brokerList,     setBrokerList]     = useState([]);
  const [gSearch,        setGSearch]        = useState('');
  const [skipBlankLsp,   setSkipBlankLsp]   = useState(true);
  const [skipDupBGG,     setSkipDupBGG]     = useState(false);
  const [gradeSettings,  setGradeSettings]  = useState({});
  const [partyType,      setPartyType]      = useState('B'); // NEW: Type A/B/C classification

  // NEW: Selected grade for garden filtering
  const [selectedGradeForGarden, setSelectedGradeForGarden] = useState(null);

  const setGradeSetting = (grade, field, val) => setGradeSettings(prev => ({
    ...prev, [grade]: { ...(prev[grade]||{}), [field]: val===''?0:parseFloat(val)||0 }
  }));

  // NEW: Copy settings from one grade to all grades below
  const copyToAllGradesBelow = (fromGrade) => {
    const fromSettings = gradeSettings[fromGrade];
    if (!fromSettings) return;

    const gradeIndex = selectedGrades.indexOf(fromGrade);
    if (gradeIndex === -1) return;

    const gradesToUpdate = selectedGrades.slice(gradeIndex + 1);

    setGradeSettings(prev => {
      const updated = { ...prev };
      gradesToUpdate.forEach(grade => {
        updated[grade] = {
          ...updated[grade],
          rate_min: fromSettings.rate_min,
          rate_max: fromSettings.rate_max,
          bags_to: fromSettings.bags_to,
          bags_from: fromSettings.bags_from,
          nwt_to: fromSettings.nwt_to,
          nwt_from: fromSettings.nwt_from
        };
      });
      return updated;
    });

    setAlert({ msg: `✅ Settings copied from ${fromGrade} to ${gradesToUpdate.length} grades below`, type: 'success' });
    setTimeout(() => setAlert(null), 2000);
  };

  const load = useCallback(async () => {
    const [p, g, gr, br, gg] = await Promise.all([
      api.get('/mapping/summary/all').catch(()=>({data:[]})),
      api.get('/mapping/gardens').catch(()=>({data:[]})),
      api.get('/marking/grades/list').catch(()=>({data:[]})),
      api.get('/mapping/brokers-available').catch(()=>({data:[]})),
      api.get('/mapping/grade-gardens').catch(()=>({data:{}})) // NEW: fetch grade-garden mapping
    ]);
    setParties(p.data); 
    setAllGardens(g.data); 
    setAllGrades(gr.data); 
    setAllBrokers(br.data);
    setGradeGardens(gg.data); // NEW: store grade-garden mapping
  }, []);

  useEffect(() => { load(); }, [load]);

  const selectParty = async (p) => {
    setSelected(p); setAlert(null);
    try {
      const r = await api.get(`/mapping/party-master/${p.id}`);
      const pm = r.data;
      setMappedGardens(pm.gardens || []);
      setBrokerList(pm.broker_list || []);
      setSkipBlankLsp(pm.skip_blank_lsp !== false);
      setSkipDupBGG(pm.skip_dup_broker_garden_grade || false);
      setPartyType(pm.party_type || 'B'); // NEW: load party type
      const gradeSamples = pm.grade_samples || {};
      const gradeRanges  = pm.grade_ranges  || {};
      const gradeBags    = pm.grade_bags    || {};
      const gradeNwt     = pm.grade_nwt     || {};
      const activeGrades = Object.keys(gradeSamples).filter(g => gradeSamples[g] > 0);
      setSelectedGrades(activeGrades);
      const gs = {};
      activeGrades.forEach(g => {
        gs[g] = { 
          max_lots: gradeSamples[g]||0, 
          rate_min: gradeRanges[g]?.min||0, 
          rate_max: gradeRanges[g]?.max||0, 
          bags_to: gradeBags[g]?.to||0,      // CHANGED: TO first
          bags_from: gradeBags[g]?.from||0,  // CHANGED: FROM second
          nwt_to: gradeNwt[g]?.to||0,        // CHANGED: TO first
          nwt_from: gradeNwt[g]?.from||0     // CHANGED: FROM second
        };
      });
      setGradeSettings(gs);
      setSelectedGradeForGarden(null); // Reset grade filter
    } catch (e) {
      setMappedGardens([]); setBrokerList([]); setSkipBlankLsp(true); setSkipDupBGG(false); 
      setSelectedGrades([]); setGradeSettings({}); setPartyType('B');
      setSelectedGradeForGarden(null);
    }
  };

  const toggleGrade = (grade) => {
    const removing = selectedGrades.includes(grade);
    setSelectedGrades(removing ? selectedGrades.filter(g=>g!==grade) : [...selectedGrades, grade]);
    if (!removing && !gradeSettings[grade])
      setGradeSettings(prev => ({ 
        ...prev, 
        [grade]: { 
          max_lots:0, 
          rate_min:0, 
          rate_max:0, 
          bags_to:0,    // CHANGED: TO first
          bags_from:0,  // CHANGED: FROM second
          nwt_to:0,     // CHANGED: TO first
          nwt_from:0    // CHANGED: FROM second
        } 
      }));
  };

  const toggleGarden = (g) => setMappedGardens(m => m.includes(g) ? m.filter(x=>x!==g) : [...m, g]);
  const toggleBroker = (b) => setBrokerList(l => l.includes(b) ? l.filter(x=>x!==b) : [...l, b]);

  const saveAll = async () => {
    if (!selected) return;
    setSaving(true);
    try {
      const grade_samples={}, grade_ranges={}, grade_bags={}, grade_nwt={};
      selectedGrades.forEach(g => {
        const s = gradeSettings[g]||{};
        grade_samples[g] = s.max_lots||0;
        grade_ranges[g]  = { min:s.rate_min||0, max:s.rate_max||0 };
        grade_bags[g]    = { to:s.bags_to||0, from:s.bags_from||0 };      // CHANGED: TO/FROM order
        grade_nwt[g]     = { to:s.nwt_to||0, from:s.nwt_from||0 };        // CHANGED: TO/FROM order
      });
      await api.post('/mapping', {
        party_id: selected.id, 
        gardens: mappedGardens,
        grade_samples, 
        grade_ranges, 
        grade_bags, 
        grade_nwt,
        broker_list: brokerList, 
        skip_blank_lsp: skipBlankLsp,
        skip_dup_broker_garden_grade: skipDupBGG,
        party_type: partyType // NEW: save party type
      });
      setAlert({ msg: `✅ Party Master saved for ${selected.party_name}`, type: 'success' });
      load();
    } catch (e) { setAlert({ msg: '❌ '+(e.response?.data?.error||e.message), type: 'error' }); }
    finally { setSaving(false); }
  };

  const addParty = async () => {
    if (!newParty.name||!newParty.code) { setAlert({ msg:'Name and code required', type:'error' }); return; }
    try { 
      await api.post('/parties',{ 
        party_name:newParty.name, 
        party_code:newParty.code,
        party_type: 'B' // Default to Type B
      }); 
      setNewParty({name:'',code:''}); 
      setAddMode(false); 
      load(); 
    }
    catch (e) { setAlert({ msg:e.response?.data?.error||e.message, type:'error' }); }
  };

  const delParty = async (id, name) => {
    if (!window.confirm(`Delete "${name}"?`)) return;
    await api.delete(`/parties/${id}`); setSelected(null); load();
  };

  const importParties = async (file) => {
    setImporting(true); setImportResult(null);
    const fd = new FormData(); fd.append('file', file);
    try { const r = await api.post('/mapping/import-parties', fd); setImportResult(r.data); load(); }
    catch (e) { setImportResult({ error: e.response?.data?.error||e.message }); }
    finally { setImporting(false); }
  };

  // NEW: Sort parties by type (A first, then B, then C)
  const sortedParties = [...parties].sort((a, b) => {
    const typeOrder = { A: 1, B: 2, C: 3 };
    const aType = a.party_type || 'B';
    const bType = b.party_type || 'B';
    if (typeOrder[aType] !== typeOrder[bType]) {
      return typeOrder[aType] - typeOrder[bType];
    }
    return a.party_name.localeCompare(b.party_name);
  });

  const filteredParties = sortedParties.filter(p =>
    p.party_name.toLowerCase().includes(search.toLowerCase()) ||
    p.party_code.toLowerCase().includes(search.toLowerCase())
  );

  // NEW: Filter gardens based on selected grade
  const gardensToShow = selectedGradeForGarden && gradeGardens[selectedGradeForGarden]
    ? gradeGardens[selectedGradeForGarden]
    : allGardens;

  const filteredGardens = gardensToShow.filter(g => g.toLowerCase().includes(gSearch.toLowerCase()));

  const totalSlots = selectedGrades.reduce((acc, g) => acc + (gradeSettings[g]?.max_lots||0), 0);
  const brokerSummary = brokerList.length===0 ? 'All' : brokerList.length===1 ? brokerList[0] : `${brokerList.length} selected`;

  const chip = (active, onClick, label, bg='#dcfce7', border='#16a34a', text='#166534') => (
    <div onClick={onClick}
      style={{ padding:'5px 11px', borderRadius:99, fontSize:12, cursor:'pointer', userSelect:'none',
        background:active?bg:'#f8fafc', border:`1.5px solid ${active?border:'#e2e8f0'}`,
        color:active?text:'#888', fontWeight:active?600:400, transition:'all 0.15s' }}>
      {label}
    </div>
  );

  // NEW: Party type badge component
  const TypeBadge = ({ type }) => {
    const colors = {
      A: { bg: '#dcfce7', border: '#16a34a', text: '#166534' },
      B: { bg: '#dbeafe', border: '#2563eb', text: '#1e40af' },
      C: { bg: '#fef3c7', border: '#f59e0b', text: '#92400e' }
    };
    const c = colors[type] || colors.B;
    return (
      <span style={{ 
        background: c.bg, 
        color: c.text, 
        border: `1.5px solid ${c.border}`,
        padding: '2px 8px', 
        borderRadius: 99, 
        fontSize: 10, 
        fontWeight: 700,
        marginLeft: 6
      }}>
        Type {type}
      </span>
    );
  };

  return (
    <div style={{ minHeight:'100vh', background:'#f8fafc', padding:20 }}>
      <div style={{ maxWidth:1400, margin:'0 auto' }}>
        <div style={{ marginBottom:20, display:'flex', justifyContent:'space-between', alignItems:'center' }}>
          <div>
            <h2 style={{ fontSize:24, marginBottom:5 }}>Party Mapping</h2>
            <p style={{ fontSize:13, color:'#888' }}>Configure party preferences: grades, gardens, brokers, and filters</p>
          </div>
        </div>

        {alert && <Alert type={alert.type} style={{ marginBottom:14 }}>{alert.msg}</Alert>}

        {addMode && (
          <Card style={{ marginBottom:14, padding:16 }}>
            <h4 style={{ fontSize:14, marginBottom:10 }}>Add New Party</h4>
            <div style={{ display:'flex', gap:10, alignItems:'flex-end' }}>
              <div style={{ flex:1 }}>
                <label style={{ fontSize:12, color:'#555', marginBottom:4, display:'block' }}>Party Code</label>
                <input value={newParty.code} onChange={e=>setNewParty({...newParty,code:e.target.value})} placeholder="ABC"
                  style={{ width:'100%', padding:'7px 10px', border:'1.5px solid #e2e8f0', borderRadius:6, fontSize:13 }} />
              </div>
              <div style={{ flex:2 }}>
                <label style={{ fontSize:12, color:'#555', marginBottom:4, display:'block' }}>Party Name</label>
                <input value={newParty.name} onChange={e=>setNewParty({...newParty,name:e.target.value})} placeholder="ABC Trading Co."
                  style={{ width:'100%', padding:'7px 10px', border:'1.5px solid #e2e8f0', borderRadius:6, fontSize:13 }} />
              </div>
              <Button variant="success" onClick={addParty}>Add Party</Button>
              <Button variant="outline" onClick={()=>{setAddMode(false);setNewParty({name:'',code:''});}}>Cancel</Button>
            </div>
          </Card>
        )}

        {importResult && (
          <Alert type={importResult.error?'error':'success'} style={{ marginBottom:14 }}>
            {importResult.error || `Imported: ${importResult.imported}, Skipped: ${importResult.skipped}`}
          </Alert>
        )}

      <div style={{ display:'flex', gap:14 }}>
        {/* ── LEFT: Party list ── */}
        <Card style={{ width:340, padding:'14px 0' }}>
          <div style={{ padding:'0 14px 10px' }}>
            <div style={{ display:'flex', gap:6, marginBottom:10 }}>
              <Button size="sm" onClick={()=>setAddMode(true)} disabled={addMode}>+ Add Party</Button>
              <label style={{ flex:1, position:'relative' }}>
                <input type="file" accept=".xlsx,.xls" onChange={e=>e.target.files[0]&&importParties(e.target.files[0])}
                  style={{ position:'absolute', opacity:0, width:0 }} />
                <Button as="span" size="sm" variant="outline" disabled={importing} style={{ width:'100%', cursor:'pointer' }}>
                  {importing?'Importing…':'📂 Import PC.xlsx'}
                </Button>
              </label>
            </div>
            <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search parties…"
              style={{ width:'100%', padding:'7px 10px', border:'1.5px solid #e2e8f0', borderRadius:6, fontSize:13 }} />
            <div style={{ fontSize: 11, color: '#888', marginTop: 8 }}>
              Sorted by Type: A → B → C (priority order)
            </div>
          </div>
          <div style={{ maxHeight:480, overflowY:'auto', padding:'0 8px 0 14px' }}>
            {filteredParties.length===0 && <div style={{ color:'#aaa', fontSize:12, padding:10, textAlign:'center' }}>{parties.length===0?'No parties. Import PC.xlsx or click + Add.':'No match.'}</div>}
            {filteredParties.map(p => (
              <div key={p.id} onClick={()=>selectParty(p)}
                style={{ padding:'6px 10px', borderRadius:6, cursor:'pointer', marginBottom:2,
                  background:selected?.id===p.id?'#dbeafe':'#f9fafb',
                  border:`1.5px solid ${selected?.id===p.id?'#93c5fd':'transparent'}`,
                  display:'flex', justifyContent:'space-between', alignItems:'center' }}>
                <div>
                  <div>
                    <span style={{ fontWeight:700, fontSize:12 }}>[{p.party_code}]</span>
                    <span style={{ fontSize:12, marginLeft:5 }}>{p.party_name}</span>
                    <TypeBadge type={p.party_type || 'B'} />
                  </div>
                  <div style={{ fontSize:10, color:'#888' }}>
                    {p.total_lots>0 ? `${p.total_lots} total lots` : p.garden_count>0 ? `${p.garden_count} gardens` : 'Not configured'}
                  </div>
                </div>
                <button onClick={e=>{e.stopPropagation();delParty(p.id,p.party_name);}} style={{ background:'none', border:'none', cursor:'pointer', color:'#ddd', fontSize:12 }}>✕</button>
              </div>
            ))}
          </div>
        </Card>

        {/* ── RIGHT: Party master (single page) ── */}
        {!selected
          ? <Card style={{ flex:1, textAlign:'center', padding:40, color:'#aaa' }}>Select a party to configure Party Master</Card>
          : (
            <div style={{ flex:1, display:'flex', flexDirection:'column', gap:14 }}>
              <Card style={{ padding:'14px 18px' }}>
                <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center' }}>
                  <div>
                    <h3 style={{ fontSize:16 }}>
                      [{selected.party_code}] {selected.party_name}
                      <TypeBadge type={partyType} />
                    </h3>
                    <div style={{ fontSize:12, color:'#888' }}>{mappedGardens.length} gardens · {totalSlots} total lots · Broker: {brokerSummary}</div>
                  </div>
                  <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
                    {/* NEW: Party Type selector */}
                    <div style={{ display: 'flex', gap: 6 }}>
                      <label style={{ fontSize: 11, color: '#555', marginRight: 4 }}>Party Type:</label>
                      {['A', 'B', 'C'].map(type => (
                        <div key={type} onClick={() => setPartyType(type)}
                          style={{
                            padding: '4px 10px',
                            borderRadius: 6,
                            fontSize: 12,
                            cursor: 'pointer',
                            background: partyType === type ? (type === 'A' ? '#dcfce7' : type === 'B' ? '#dbeafe' : '#fef3c7') : '#f8fafc',
                            border: `1.5px solid ${partyType === type ? (type === 'A' ? '#16a34a' : type === 'B' ? '#2563eb' : '#f59e0b') : '#e2e8f0'}`,
                            color: partyType === type ? (type === 'A' ? '#166534' : type === 'B' ? '#1e40af' : '#92400e') : '#888',
                            fontWeight: partyType === type ? 700 : 400
                          }}>
                          {type}
                        </div>
                      ))}
                    </div>
                    <Button variant="success" onClick={saveAll} disabled={saving}>{saving?'Saving…':'💾 Save Party Master'}</Button>
                  </div>
                </div>
              </Card>

              {/* Section 1: Grade settings */}
              <Card style={{ padding:16 }}>
                <SectionTitle n="1">Grade Settings — Select grades and configure Max Lots, Rate Range, Bags, Net Wt</SectionTitle>
                <div style={{ display:'flex', gap:8, flexWrap:'wrap', marginBottom:12 }}>
                  {allGrades.map(g => chip(selectedGrades.includes(g), ()=>toggleGrade(g), g))}
                </div>
                {selectedGrades.length>0 && (
                  <div style={{ overflowX:'auto' }}>
                    <table style={{ borderCollapse:'collapse', fontSize:12, width:'100%' }}>
                      <thead>
                        <tr style={{ background:'#f0f4f8' }}>
                          {['Grade','Max Lots','Rate Min ₹','Rate Max ₹','Bags TO','Bags FROM','Net Wt TO','Net Wt FROM','Actions'].map(h => (
                            <th key={h} style={{ padding:'8px 12px', textAlign:'center', fontWeight:700, color:'#444' }}>{h}</th>
                          ))}
                        </tr>
                      </thead>
                      <tbody>
                        {selectedGrades.map((g,i) => {
                          const s = gradeSettings[g]||{};
                          return (
                            <tr key={g} style={{ borderBottom:'1px solid #f0f4f8', background:i%2===0?'#fff':'#fafbfc' }}>
                              <td style={{ padding:'8px 12px', textAlign:'center' }}>
                                <span style={{ background:'#dbeafe', color:'#1e40af', padding:'2px 10px', borderRadius:99, fontWeight:700 }}>{g}</span>
                              </td>
                              <td style={{ padding:'8px 12px', textAlign:'center' }}>
                                <input type="number" min="0" value={s.max_lots||''} onChange={e=>setGradeSetting(g,'max_lots',e.target.value)} placeholder="0"
                                  style={{ width:70, padding:'5px 8px', textAlign:'center', border:`2px solid ${s.max_lots>0?'#1a7a4a':'#cbd5e0'}`, borderRadius:6, fontSize:13, fontWeight:s.max_lots>0?700:400, color:s.max_lots>0?'#166534':'#555' }} />
                              </td>
                              <td style={{ padding:'8px 12px', textAlign:'center' }}><NumCell value={s.rate_min} onChange={v=>setGradeSetting(g,'rate_min',v)} /></td>
                              <td style={{ padding:'8px 12px', textAlign:'center' }}><NumCell value={s.rate_max} onChange={v=>setGradeSetting(g,'rate_max',v)} /></td>
                              {/* CHANGED: TO column first */}
                              <td style={{ padding:'8px 12px', textAlign:'center' }}><NumCell value={s.bags_to}   onChange={v=>setGradeSetting(g,'bags_to',v)} /></td>
                              <td style={{ padding:'8px 12px', textAlign:'center' }}><NumCell value={s.bags_from} onChange={v=>setGradeSetting(g,'bags_from',v)} /></td>
                              <td style={{ padding:'8px 12px', textAlign:'center' }}><NumCell value={s.nwt_to}    onChange={v=>setGradeSetting(g,'nwt_to',v)} placeholder="0.00" /></td>
                              <td style={{ padding:'8px 12px', textAlign:'center' }}><NumCell value={s.nwt_from}  onChange={v=>setGradeSetting(g,'nwt_from',v)} placeholder="0.00" /></td>
                              {/* NEW: Copy to All Grades Below button */}
                              <td style={{ padding:'8px 12px', textAlign:'center' }}>
                                {i < selectedGrades.length - 1 && (
                                  <button
                                    onClick={() => copyToAllGradesBelow(g)}
                                    title="Copy this row's settings to all grades below"
                                    style={{
                                      padding: '4px 8px',
                                      fontSize: 11,
                                      background: '#f0f4f8',
                                      border: '1px solid #cbd5e0',
                                      borderRadius: 4,
                                      cursor: 'pointer',
                                      color: '#555',
                                      fontWeight: 600
                                    }}>
                                    ⬇ Copy Below
                                  </button>
                                )}
                              </td>
                            </tr>
                          );
                        })}
                      </tbody>
                      <tfoot>
                        <tr style={{ background:'#f0f4f8', fontWeight:700 }}>
                          <td style={{ padding:'7px 12px', fontSize:12, color:'#444' }}>Total Slots</td>
                          <td style={{ padding:'7px 12px', textAlign:'center', color:'#1a7a4a', fontSize:14 }}>{totalSlots}</td>
                          <td colSpan={7}></td>
                        </tr>
                      </tfoot>
                    </table>
                  </div>
                )}
              </Card>

              {/* Section 2: Gardens — Grade-based filtering */}
              <Card style={{ padding:16 }}>
                <SectionTitle n="2">Gardens — Select grade first to filter gardens, then select gardens</SectionTitle>
                <div style={{ fontSize:12, color:'#888', marginBottom:10 }}>
                  If no garden selected, grade filter settings above will apply to all matching lots.
                  If gardens selected, only one lot per garden+grade+broker combination will be marked.
                </div>

                {/* NEW: Grade filter chips */}
                <div style={{ marginBottom: 12 }}>
                  <div style={{ fontSize: 11, fontWeight: 700, color: '#444', marginBottom: 6 }}>
                    Filter gardens by grade (optional):
                  </div>
                  <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap', marginBottom: 8 }}>
                    <div
                      onClick={() => setSelectedGradeForGarden(null)}
                      style={{
                        padding: '4px 10px',
                        borderRadius: 99,
                        fontSize: 12,
                        cursor: 'pointer',
                        background: selectedGradeForGarden === null ? '#dbeafe' : '#f8fafc',
                        border: `1.5px solid ${selectedGradeForGarden === null ? '#2563eb' : '#e2e8f0'}`,
                        color: selectedGradeForGarden === null ? '#1e40af' : '#888',
                        fontWeight: selectedGradeForGarden === null ? 600 : 400
                      }}>
                      All Grades
                    </div>
                    {selectedGrades.map(grade => (
                      <div
                        key={grade}
                        onClick={() => setSelectedGradeForGarden(grade)}
                        style={{
                          padding: '4px 10px',
                          borderRadius: 99,
                          fontSize: 12,
                          cursor: 'pointer',
                          background: selectedGradeForGarden === grade ? '#dbeafe' : '#f8fafc',
                          border: `1.5px solid ${selectedGradeForGarden === grade ? '#2563eb' : '#e2e8f0'}`,
                          color: selectedGradeForGarden === grade ? '#1e40af' : '#888',
                          fontWeight: selectedGradeForGarden === grade ? 600 : 400
                        }}>
                        {grade}
                        {gradeGardens[grade] && ` (${gradeGardens[grade].length})`}
                      </div>
                    ))}
                  </div>
                  {selectedGradeForGarden && (
                    <div style={{ fontSize: 11, color: '#2563eb', fontStyle: 'italic' }}>
                      Showing {filteredGardens.length} gardens for grade {selectedGradeForGarden}
                    </div>
                  )}
                </div>

                <div style={{ display:'flex', gap:8, marginBottom:10, alignItems:'center' }}>
                  <input value={gSearch} onChange={e=>setGSearch(e.target.value)} placeholder="Search gardens…"
                    style={{ flex:1, padding:'7px 10px', border:'1.5px solid #e2e8f0', borderRadius:6, fontSize:13 }} />
                  <Button size="sm" variant="outline" onClick={()=>setMappedGardens([...filteredGardens])}>Select All</Button>
                  <Button size="sm" variant="outline" onClick={()=>setMappedGardens([])}>Clear</Button>
                  <span style={{ fontSize:12, color:'#888', whiteSpace:'nowrap' }}>{mappedGardens.length} selected</span>
                </div>
                <div style={{ display:'flex', gap:7, flexWrap:'wrap', maxHeight:200, overflowY:'auto' }}>
                  {filteredGardens.length===0
                    ? <div style={{ color:'#aaa', fontSize:13 }}>
                        {selectedGradeForGarden 
                          ? `No gardens for grade ${selectedGradeForGarden}. Import Catalogue first.`
                          : 'No gardens. Import Catalogue first.'}
                      </div>
                    : filteredGardens.map(g => chip(mappedGardens.includes(g), ()=>toggleGarden(g), g))
                  }
                </div>
              </Card>

              {/* Section 3: Brokers */}
              <Card style={{ padding:16 }}>
                <SectionTitle n="3">Broker List — leave empty for All Brokers</SectionTitle>
                <div style={{ display:'flex', gap:7, flexWrap:'wrap' }}>
                  {allBrokers.map(b => chip(brokerList.includes(b), ()=>toggleBroker(b), b, '#dbeafe', '#1a3c5e', '#1e40af'))}
                </div>
                {brokerList.length>0 && <div style={{ fontSize:11, color:'#1e40af', marginTop:6 }}>Selected: {brokerList.join(', ')}</div>}
              </Card>

              {/* Section 4: Skip options */}
              <Card style={{ padding:16 }}>
                <SectionTitle n="4">Skip Options</SectionTitle>
                <label style={{ display:'flex', alignItems:'center', gap:8, fontSize:13, cursor:'pointer', marginBottom:10 }}>
                  <input type="checkbox" checked={skipBlankLsp} onChange={e=>setSkipBlankLsp(e.target.checked)} style={{ width:16, height:16 }} />
                  Want to skip lots when Last Sale Price (L.S.P.) is blank
                </label>
                <label style={{ display:'flex', alignItems:'center', gap:8, fontSize:13, cursor:'pointer' }}>
                  <input type="checkbox" checked={skipDupBGG} onChange={e=>setSkipDupBGG(e.target.checked)} style={{ width:16, height:16 }} />
                  Want to skip extra lots when Broker, Garden &amp; Grade is same (mark first lot only)
                </label>
              </Card>
            </div>
          )
        }
      </div>
    </div>
    </div>
  );
}
